function run(input){
  var a=input.a, b=input.b;
  switch(input.op){
    case 'add': return {result: a+b};
    case 'sub': return {result: a-b};
    case 'mul': return {result: a*b};
    case 'div': if(b===0) throw new Error('Zero se bhaag nahi'); return {result: a/b};
    case 'pow': return {result: Math.pow(a,b)};
    case 'pct': return {result: (a*b)/100};
    default: throw new Error('Galat op: '+input.op);
  }
}
